--
-- Table structure for table `address_zone_mapping`
--

CREATE TABLE `address_zone_mapping` (
  `id` int(11) NOT NULL,
  `store_id` int(11) NOT NULL,
  `external_zone_id` varchar(50) NOT NULL,
  `external_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`external_data`)),
  `external_country_id` int(11) DEFAULT NULL,
  `internal_zone_id` int(11) DEFAULT NULL,
  `zone_mapping_remarks` varchar(50) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

