CREATE TABLE `post_items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `post_id` bigint(20) UNSIGNED NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `title_ar` varchar(255) DEFAULT NULL,
  `title_en` varchar(255) DEFAULT NULL,
  `subtitle_ar` varchar(255) DEFAULT NULL,
  `subtitle_en` varchar(255) DEFAULT NULL,
  `description_ar` longtext DEFAULT NULL,
  `description_en` longtext DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `extra_image` varchar(255) DEFAULT NULL,
  `link` varchar(255) DEFAULT NULL,
  `btn_text_ar` varchar(100) DEFAULT NULL,
  `btn_text_en` varchar(100) DEFAULT NULL,
  `rating` tinyint(3) UNSIGNED DEFAULT 5,
  `price` varchar(100) DEFAULT NULL,
  `sort` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
