INSERT INTO `post_items` (`id`, `post_id`, `email`, `title_ar`, `title_en`, `subtitle_ar`, `subtitle_en`, `description_ar`, `description_en`, `image`, `extra_image`, `link`, `btn_text_ar`, `btn_text_en`, `rating`, `price`, `sort`, `status`, `created_at`, `updated_at`) VALUES
(1, 24, NULL, NULL, 'Mustafa', NULL, NULL, NULL, 'Of course my testimony about you is biased, but you deserve to know that you\'re truly one of the best coaches I\'ve worked with. You\'re very attentive to every detail of the workout, you explain every exercise in a simple way, and you follow up on performance step by step so it\'s done correctly and gives the best results. The training program was organized and suited to my level, and you always motivate me to keep going and improve myself. Thanks for your care and effort, and may God always grant you success. 💪', 'upload/posts/1877410628286387.jpg', NULL, NULL, NULL, NULL, 5, NULL, 10, 'active', '2026-09-26 18:58:17', '2026-09-26 18:58:17'),
(2, 24, NULL, NULL, 'Hamza', NULL, NULL, NULL, 'Honestly coach, you\'ve been so committed with me and followed up with me every single day. I lost a lot of weight during the period I trained with you, which was less than 3 months, and of course I found a very satisfying result ❤️❤️Honestly coach, you\'ve been so committed with me and followed up with me every single day. I lost a lot of weight during the period I trained with you, which was less than 3 months, and of course I found a very satisfying result ❤️❤️', 'upload/posts/1877410818855127.jpg', NULL, NULL, NULL, NULL, 5, NULL, 2, 'active', '2026-09-26 19:01:19', '2026-09-26 19:01:19'),
(3, 24, NULL, NULL, 'Mohamed', NULL, NULL, NULL, 'Honestly bro, no need for words — the transformation is unbelievable. Everything changed: my shape, my body, my movement, everything. I went from 130 to 90 kg in 9 months with no starvation, and without losing any muscle. Amazing work, and what\'s coming next will be even better, God willing.', 'upload/posts/1877411122931584.jpg', NULL, NULL, NULL, NULL, 4, NULL, 3, 'active', '2026-09-26 19:06:09', '2026-09-26 19:06:09'),
(4, 24, NULL, NULL, 'Eyad', NULL, NULL, NULL, 'The follow-up was excellent; he monitored me 24 hours a day, tracking the number of meals I ate and the progress at each stage. Overall, I was very happy that I was training with him.', 'upload/posts/1877411164858937.jpg', NULL, NULL, NULL, NULL, 5, NULL, 3, 'active', '2026-09-26 19:06:49', '2026-09-26 19:06:49');

